const DS_REASONING = { off: 'off', low: 'low', high: 'high', max: 'max' };
const ANTHROPIC_REASONING = { off: null, low: 'low', high: 'high' };

function m(id, name, input = TEXT, extras = {}) {
  return {
    id,
    name,
    contextWindow: extras.ctx || 128000,
    maxTokens: extras.max || 8192,
    input,
    reasoningEfforts: extras.re || false,
    defaultEffort: extras.de || null,
  };
}

